def format_bytes(n):
    if n < 1024:
        return f"{n} B"
    for unit in ["KB", "MB", "GB", "TB", "PB"]:
        n /= 1024
        if n < 1024 or unit == "PB":
            return f"{n:.1f} {unit}"

from decimal import Decimal, ROUND_HALF_UP


def round_half_up(x, ndigits=0):
    # str() gives the shortest repr, so 2.675 is treated as written, not as 2.67499999...
    return float(Decimal(str(x)).quantize(Decimal(1).scaleb(-ndigits), rounding=ROUND_HALF_UP))

def page_count(total_items, per_page):
    return -(-total_items // per_page)


def page(items, number, per_page):
    """Return page `number` (1-based) of `items`."""
    start = (number - 1) * per_page
    return items[start:start + per_page]

import re


def _positive_int(value, name):
    if isinstance(value, int) and not isinstance(value, bool):
        n = value
    elif isinstance(value, str) and re.fullmatch(r"[0-9]+", value):
        n = int(value)
    else:
        raise ValueError(f"{name} must be a positive integer")
    if n < 1:
        raise ValueError(f"{name} must be a positive integer")
    return n


def parse_pagination(params):
    page = _positive_int(params.get("page", 1), "page")
    page_size = _positive_int(params.get("page_size", 20), "page_size")
    return {"page": page, "page_size": min(page_size, 100)}

def merge_intervals(intervals):
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

import csv


def total_amount(path):
    with open(path, newline="") as f:
        return float(sum(float(row["amount"]) for row in csv.DictReader(f)))

import re


def slugify(title):
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")

def flatten(nested):
    # Iterative so very deep nesting can't hit the recursion limit.
    out, stack = [], [iter(nested)]
    while stack:
        for x in stack[-1]:
            if isinstance(x, list):
                stack.append(iter(x))
                break
            out.append(x)
        else:
            stack.pop()
    return out

def parse_amount(text):
    return float(str(text).replace(",", ""))


def order_total(lines):
    return sum(parse_amount(line["amount"]) for line in lines)


def refund_total(lines):
    return sum(parse_amount(line["amount"]) for line in lines if line.get("refunded"))

import functools
import time


def retry(times, delay):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == times - 1:
                        raise
                    time.sleep(delay)
        return wrapper
    return decorator
